document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("progressBar"),e=document.getElementById("backToTop");if(t||e){let o=!1;e&&e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}),window.addEventListener("scroll",()=>{o||(window.requestAnimationFrame(()=>{const n=window.scrollY||document.documentElement.scrollTop;if(t){const s=document.documentElement.scrollHeight-document.documentElement.clientHeight,c=s>0?n/s*100:0;t.style.width=c+"%"}e&&e.classList.toggle("show",n>300),o=!1}),o=!0)},{passive:!0})}});
